import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.test.web.servlet.setup.MockMvcBuilders;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;

@RestController
public class StockController {
    int stock = 12;

    @PostMapping("/stocks/ship")
    public ResponseEntity<String> ship(@RequestParam("qty") int qty) {
        if (qty <= 0) {
            return ResponseEntity.badRequest().body("bad qty");
        }
        if (qty > stock) {
            return ResponseEntity.status(409).body("short: " + stock);
        }
        stock -= qty;
        return ResponseEntity.ok("left: " + stock);
    }
}

MockMvc mvc = MockMvcBuilders
        .standaloneSetup(new StockController())
        .build();

var res = mvc.perform(post("/stocks/ship").param("qty", "3"))
        .andReturn()
        .getResponse();
System.out.println("status = " + res.getStatus());
System.out.println("body   = " + res.getContentAsString());

// テストではこう書く(期待と違えば AssertionError)
void test() throws Exception {
    mvc.perform(post("/stocks/ship").param("qty", "0"))
            .andExpect(status().isBadRequest());
    mvc.perform(post("/stocks/ship").param("qty", "1"))
            .andExpect(status().isOk())
            .andExpect(content().string("left: 8"));
}

test();
System.out.println("andExpect はすべて成功しました");

